<template><AdminLayout><section dir="rtl" class="purchase-page"><header class="purchase-title"><div><h1>خرید و تأمین کالا</h1><p>سفارش را ثبت کنید؛ سند خرید بلافاصله برای مشاهده و چاپ آماده می‌شود.</p></div><button class="invoice-button primary" @click="openForm">ثبت خرید</button></header><p v-if="error" role="alert" class="invoice-feedback">{{ error }}</p><p v-if="loading" role="status">در حال دریافت خریدها…</p><div v-else-if="!orders.length" class="purchase-empty">هنوز خریدی ثبت نشده است. برای شروع، «ثبت خرید» را انتخاب کنید.</div><div v-else class="purchase-table"><table><thead><tr><th>شماره خرید</th><th>تأمین‌کننده</th><th>تاریخ</th><th>وضعیت</th><th>مبلغ / تومان</th><th>سند</th></tr></thead><tbody><tr v-for="order in orders" :key="order.id"><td dir="ltr">{{ order.purchase_number || order.reference_number || order.id }}</td><td>{{ order.supplier_name || supplierName(order.supplier) }}</td><td>{{ order.purchase_date }}</td><td>{{ statuses[order.status] || order.status }}</td><td>{{ number(order.total_amount || order.total || 0) }}</td><td><button class="invoice-button" @click="selected = order">مشاهده فاکتور</button></td></tr></tbody></table></div><ReceiptPrint :show="!!selected" :purchase-order="selected" @close="selected = null" />
<Teleport to="body"><div v-if="formVisible" class="purchase-modal" role="dialog" aria-modal="true" aria-label="ثبت خرید"><form class="purchase-form" @submit.prevent="save"><header><h2>ثبت خرید جدید</h2><button type="button" aria-label="بستن" @click="formVisible = false">×</button></header><p v-if="formError" class="invoice-feedback" role="alert">{{ formError }}</p><p v-if="selectorsLoading" role="status">در حال دریافت کالاها و طرف‌حساب‌ها…</p><p v-else-if="!suppliers.length || !products.length || !warehouses.length" class="invoice-feedback">برای ثبت خرید، حداقل یک تأمین‌کننده، کالا و انبار فعال لازم است. ابتدا اطلاعات پایه را ثبت کنید.</p><div class="purchase-fields"><label>تأمین‌کننده<select v-model="form.supplier" required><option value="">انتخاب تأمین‌کننده</option><option v-for="item in suppliers" :key="item.id" :value="item.id">{{ item.name }}</option></select></label><label>انبار<select v-model="form.warehouse" required><option value="">انتخاب انبار</option><option v-for="item in warehouses" :key="item.id" :value="item.id">{{ item.name }}</option></select></label><label>تاریخ خرید<input v-model="form.purchase_date" type="date" required /></label><label>وضعیت دریافت<select v-model="form.status"><option value="ordered">سفارش ثبت شده — بدون افزایش موجودی</option><option value="received">دریافت کامل در انبار — افزایش موجودی</option></select></label><label>شماره مرجع<input v-model.trim="form.reference_number" maxlength="50" required /></label></div><p class="stock-help">{{ form.status === 'received' ? 'با ثبت، تمام تعداد اقلام به موجودی انبار انتخاب‌شده اضافه می‌شود.' : 'این خرید فقط سفارش است؛ هنوز کالایی وارد موجودی نمی‌شود.' }}</p><fieldset><legend>اقلام خرید · قیمت‌ها به تومان</legend><div v-for="(row,index) in form.items" :key="row.key" class="purchase-row"><label>کالا<select v-model="row.product" required @change="setPrice(row)"><option value="">انتخاب کالا</option><option v-for="product in products" :key="product.id" :value="product.id">{{ product.name }} — {{ product.code }}</option></select></label><label>تعداد<input v-model.number="row.quantity" type="number" min="0.01" step="0.01" required /></label><label>بهای واحد<input v-model.number="row.unit_price" type="number" min="0" step="1" required /></label><button type="button" class="invoice-button" :disabled="form.items.length === 1" :aria-label="`حذف قلم ${index+1}`" @click="form.items.splice(index,1)">حذف</button></div><button type="button" class="invoice-button" @click="addRow">+ افزودن قلم</button></fieldset><div class="purchase-fields"><label>تخفیف سند / تومان<input v-model.number="form.discount_amount" type="number" min="0" step="1" /></label><label>مالیات / تومان<input v-model.number="form.tax_amount" type="number" min="0" step="1" /></label></div><label>یادداشت داخلی<textarea v-model="form.notes" rows="3"></textarea></label><footer><span>پس از ثبت، فاکتور به‌صورت خودکار نمایش داده می‌شود.</span><button class="invoice-button primary" :disabled="saving || selectorsLoading || !suppliers.length || !products.length || !warehouses.length">{{ saving ? 'در حال ثبت…' : 'ثبت خرید و نمایش سند' }}</button></footer></form></div></Teleport></section></AdminLayout></template>
<script setup>
import { ref, onMounted } from 'vue'
import { useQuickCreate } from '@/composables/useQuickCreate'
import AdminLayout from '@/components/layout/AdminLayout.vue'
import ReceiptPrint from '@/components/sales/ReceiptPrint.vue'
import api, { purchasesAPI } from '@/services/api'
const orders=ref([]),suppliers=ref([]),products=ref([]),warehouses=ref([]),loading=ref(true),error=ref(''),selected=ref(null),formVisible=ref(false),formError=ref(''),selectorsLoading=ref(false),saving=ref(false),form=ref({})
const statuses={draft:'پیش‌نویس',ordered:'سفارش داده شده',partial:'دریافت جزئی',received:'دریافت شده',cancelled:'لغو شده'}
const number=value=>new Intl.NumberFormat('fa-IR').format(Number(value))
const supplierName=id=>suppliers.value.find(item=>item.id===id)?.name || '—'
async function allPages(path){const rows=[];let page=1;while(true){const {data}=await api.get(path,{params:{page}});rows.push(...(data.results||data));if(!data.next) return rows;page++}}
async function load(){loading.value=true;error.value='';try{orders.value=await allPages('/purchases/purchases/')}catch{error.value='دریافت خریدها ممکن نشد. اتصال و مجوز دسترسی را بررسی کنید.'}finally{loading.value=false}}
const addRow=()=>form.value.items.push({key:crypto.randomUUID(),product:'',quantity:1,unit_price:0})
const setPrice=row=>{row.unit_price=Number(products.value.find(item=>item.id===row.product)?.purchase_price||0)}
async function openForm(){form.value={supplier:'',warehouse:'',status:'ordered',purchase_date:new Date(Date.now() - new Date().getTimezoneOffset() * 60000).toISOString().slice(0,10),reference_number:'',discount_amount:0,tax_amount:0,notes:'',items:[]};addRow();formError.value='';formVisible.value=true;selectorsLoading.value=true;try{[suppliers.value,products.value,warehouses.value]=await Promise.all([allPages('/purchases/suppliers/'),allPages('/products/'),allPages('/inventory/warehouses/')]);products.value=products.value.filter(item=>item.is_active!==false);suppliers.value=suppliers.value.filter(item=>item.is_active!==false);warehouses.value=warehouses.value.filter(item=>item.is_active!==false)}catch{formError.value='دریافت اطلاعات پایه ممکن نشد؛ فرم را ببندید و دوباره تلاش کنید.'}finally{selectorsLoading.value=false}}
async function save(){if(saving.value)return;saving.value=true;formError.value='';try{const payload={...form.value,items:form.value.items.map(row=>({product:row.product,quantity:row.quantity,unit_price:row.unit_price,received_quantity:form.value.status==='received'?row.quantity:0,notes:''}))};const {data}=await purchasesAPI.createPurchaseOrder(payload);formVisible.value=false;selected.value={id:data.id};await load()}catch(failure){const details=failure.response?.data;formError.value=details?JSON.stringify(details):'ثبت خرید ممکن نشد. اتصال را بررسی کنید؛ پیش از تلاش دوباره فهرست خریدها را کنترل کنید.'}finally{saving.value=false}}
useQuickCreate('purchase', '/purchases', openForm)
onMounted(load)
</script>
<style>.purchase-page{color:#243a40}.purchase-title{display:flex;justify-content:space-between;gap:20px;align-items:center;margin-bottom:24px}.purchase-title h1{font-size:25px;font-weight:700}.purchase-title p{font-size:13px;color:#52646a;margin-top:8px}.purchase-table{overflow:auto;background:#fff;border:1px solid #d9e2e3;border-radius:6px}.purchase-table table{width:100%;text-align:right;font-size:13px}.purchase-table th,.purchase-table td{padding:16px;border-bottom:1px solid #e4ebeb;white-space:nowrap}.purchase-table th{background:#f0f5f4}.purchase-empty{padding:45px;background:white;border:1px dashed #b7c8c8;text-align:center}.purchase-modal{position:fixed;inset:0;z-index:99999;background:#102b35b3;padding:30px 16px;overflow:auto;display:flex;align-items:flex-start;justify-content:center;direction:rtl}.purchase-form{width:100%;max-width:850px;background:white;padding:28px;border-radius:8px;color:#243a40}.purchase-form header{display:flex;justify-content:space-between;margin-bottom:25px}.purchase-form h2{font-size:22px;font-weight:700}.purchase-form header button{font-size:26px}.purchase-fields{display:grid;grid-template-columns:1fr 1fr;gap:18px;margin-bottom:20px}.purchase-form label{display:block;font-size:12px;font-weight:600}.purchase-form input,.purchase-form select,.purchase-form textarea{display:block;width:100%;margin-top:6px;padding:10px;border:1px solid #b7c8c8;border-radius:5px;background:white;font-size:13px;color:#243a40}.purchase-form input:focus,.purchase-form select:focus,.purchase-form textarea:focus{outline:2px solid #9dc7c1}.purchase-form fieldset{border-top:1px solid #d9e2e3;padding:20px 0;margin:20px 0}.purchase-form legend{font-size:13px;padding-left:12px}.purchase-row{display:grid;grid-template-columns:2fr 1fr 1fr auto;gap:12px;align-items:end;margin-bottom:16px}.stock-help{font-size:12px;color:#245a56;background:#eff5f3;padding:12px}.purchase-form footer{border-top:1px solid #d9e2e3;padding-top:20px;margin-top:20px;display:flex;align-items:center;justify-content:space-between;gap:16px;font-size:11px;color:#52646a}@media(max-width:600px){.purchase-title{align-items:flex-start;flex-direction:column}.purchase-fields{grid-template-columns:1fr}.purchase-row{grid-template-columns:1fr 1fr}.purchase-row label:first-child{grid-column:1/-1}.purchase-form{padding:20px}.purchase-modal{padding:10px}.purchase-form footer{flex-direction:column;align-items:stretch}}</style>
<style>
/* Workspace surfaces only: invoice paper and print styles retain their own palette. */
.dark .purchase-page, .dark .purchase-form { color: #f2f4f7; }
.dark .purchase-title p, .dark .purchase-form footer { color: #d0d5dd; }
.dark .purchase-empty, .dark .purchase-table, .dark .purchase-form { background: #1d2939; border-color: #475467; }
.dark .purchase-table th { background: #344054; color: #f2f4f7; }
.dark .purchase-table th, .dark .purchase-table td, .dark .purchase-form fieldset, .dark .purchase-form footer { border-color: #475467; }
.dark .purchase-form input, .dark .purchase-form select, .dark .purchase-form textarea { background: #101828; color: #f2f4f7; border-color: #667085; color-scheme: dark; }
.dark .purchase-form input:focus, .dark .purchase-form select:focus, .dark .purchase-form textarea:focus { outline-color: #6ee7b7; }
.dark .purchase-form .stock-help { background: #064e3b; color: #d1fae5; }
.dark .purchase-title .invoice-button, .dark .purchase-table .invoice-button, .dark .purchase-form .invoice-button { color: #f2f4f7; background: #344054; border-color: #667085; }
.dark .purchase-title .invoice-button.primary, .dark .purchase-form .invoice-button.primary { background: #0f766e; color: white; border-color: #2dd4bf; }
</style>
